-- Create "schema_metadata" table
CREATE TABLE `schema_metadata` (`singleton` integer NOT NULL, `format_id` text NOT NULL, `data_epoch` integer NOT NULL, `layout_version` integer NOT NULL, `schema_fingerprint` text NOT NULL, `initialization_state` text NOT NULL, PRIMARY KEY (`singleton`), CONSTRAINT `metadata_singleton` CHECK (singleton = 1), CONSTRAINT `metadata_versions` CHECK (data_epoch > 0 AND layout_version > 0), CONSTRAINT `metadata_initialized` CHECK (initialization_state = 'ready'));
-- Create "spaces" table
CREATE TABLE `spaces` (`space_id` text NOT NULL, `revision` integer NOT NULL, `bundle` text NOT NULL, PRIMARY KEY (`space_id`), CONSTRAINT `space_revision` CHECK (revision >= 0));
-- Create "node_certificates" table
CREATE TABLE `node_certificates` (`space_id` text NOT NULL, `node_id` text NOT NULL, `public_key` text NOT NULL, PRIMARY KEY (`space_id`, `node_id`), CONSTRAINT `node_certificates_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`));
-- Create "local_devices" table
CREATE TABLE `local_devices` (`space_id` text NOT NULL, `device_id` text NOT NULL, `public_key` text NOT NULL, PRIMARY KEY (`space_id`, `device_id`), CONSTRAINT `local_devices_certificate` FOREIGN KEY (`space_id`, `device_id`) REFERENCES `node_certificates` (`space_id`, `node_id`));
-- Create "events" table
CREATE TABLE `events` (`space_id` text NOT NULL, `resource_id` text NOT NULL, `hash` text NOT NULL, `scope_id` text NOT NULL, `author` text NOT NULL, `sequence` integer NOT NULL, `envelope` text NOT NULL, `status` text NOT NULL, PRIMARY KEY (`space_id`, `hash`), CONSTRAINT `events_author` FOREIGN KEY (`space_id`, `author`) REFERENCES `node_certificates` (`space_id`, `node_id`), CONSTRAINT `events_resource` FOREIGN KEY (`space_id`, `resource_id`) REFERENCES `resource_records` (`space_id`, `resource_id`), CONSTRAINT `event_sequence` CHECK (sequence > 0), CONSTRAINT `event_status` CHECK (status IN ('pending', 'ready', 'conflict', 'invalid')));
-- Create index "events_author_sequence" to table: "events"
CREATE INDEX `events_author_sequence` ON `events` (`space_id`, `scope_id`, `author`, `sequence`);
-- Create index "events_scope" to table: "events"
CREATE INDEX `events_scope` ON `events` (`space_id`, `scope_id`);
-- Create "blobs" table
CREATE TABLE `blobs` (`space_id` text NOT NULL, `hash` text NOT NULL, `size` integer NOT NULL, `content` blob NOT NULL, PRIMARY KEY (`space_id`, `hash`), CONSTRAINT `blobs_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `blob_nonnegative_size` CHECK (size >= 0));
-- Create "conversations" table
CREATE TABLE `conversations` (`space_id` text NOT NULL, `resource_id` text NOT NULL, `conversation_id` text NOT NULL, `title` text NOT NULL, PRIMARY KEY (`space_id`, `conversation_id`), CONSTRAINT `conversations_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `conversations_resource` FOREIGN KEY (`space_id`, `resource_id`) REFERENCES `resource_records` (`space_id`, `resource_id`));
-- Create "messages" table
CREATE TABLE `messages` (`space_id` text NOT NULL, `conversation_id` text NOT NULL, `event_hash` text NOT NULL, `message_id` text NOT NULL, `role` text NOT NULL, `text` text NOT NULL, `created_at_ms` integer NOT NULL, `ordinal` integer NOT NULL, PRIMARY KEY (`space_id`, `event_hash`), CONSTRAINT `messages_source` FOREIGN KEY (`space_id`, `event_hash`) REFERENCES `events` (`space_id`, `hash`));
-- Create "tasks" table
CREATE TABLE `tasks` (`space_id` text NOT NULL, `conversation_id` text NOT NULL, `task_id` text NOT NULL, `title` text NOT NULL, `goal` text NOT NULL, `acceptance` text NOT NULL, `status` text NOT NULL, `detail` text NOT NULL, `event_hash` text NOT NULL, PRIMARY KEY (`space_id`, `conversation_id`, `task_id`), CONSTRAINT `tasks_source` FOREIGN KEY (`space_id`, `event_hash`) REFERENCES `events` (`space_id`, `hash`));
-- Create "execution_sessions" table
CREATE TABLE `execution_sessions` (`space_id` text NOT NULL, `target_node` text NOT NULL, `session_id` text NOT NULL, `revision` integer NOT NULL, `record` text NOT NULL, PRIMARY KEY (`space_id`, `target_node`, `session_id`), CONSTRAINT `sessions_node` FOREIGN KEY (`space_id`, `target_node`) REFERENCES `node_certificates` (`space_id`, `node_id`), CONSTRAINT `session_revision` CHECK (revision >= 0));
-- Create "operations" table
CREATE TABLE `operations` (`space_id` text NOT NULL, `operation_id` text NOT NULL, `target_node` text NOT NULL, `session_id` text NULL, `request` text NOT NULL, `state` text NOT NULL, `control` integer NOT NULL DEFAULT 0, `result` text NOT NULL, PRIMARY KEY (`space_id`, `operation_id`), CONSTRAINT `operations_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `operation_control` CHECK (control IN (0,1)), CONSTRAINT `operation_request_json` CHECK (json_valid(request)), CONSTRAINT `operation_request_session` CHECK (COALESCE(CASE json_extract(request, '$.action.type') WHEN 'command' THEN session_id IS NULL AND json_type(request, '$.session_id') = 'null' AND json_type(request, '$.task_id') = 'null' AND COALESCE(json_type(request, '$.binding'), 'null') = 'null' AND json_extract(request, '$.expected_revision') = 0 ELSE json_extract(request, '$.action.type') IN ('open','read','send','steer','interrupt','respond_request') AND session_id IS NOT NULL AND length(session_id) > 0 AND json_extract(request, '$.session_id') = session_id END, 0)));
-- Create index "operations_session" to table: "operations"
CREATE INDEX `operations_session` ON `operations` (`space_id`, `target_node`, `session_id`, `state`);
-- Create index "operations_request_reference" to table: "operations"
CREATE UNIQUE INDEX `operations_request_reference` ON `operations` (`space_id`, `operation_id`, `request`);
-- Create "resource_reservations" table
CREATE TABLE `resource_reservations` (`space_id` text NOT NULL, `operation_id` text NOT NULL, `target_node` text NOT NULL, `resource` text NOT NULL, PRIMARY KEY (`space_id`, `operation_id`, `resource`), CONSTRAINT `reservations_operation` FOREIGN KEY (`space_id`, `operation_id`) REFERENCES `operations` (`space_id`, `operation_id`));
-- Create "continuation_claims" table
CREATE TABLE `continuation_claims` (`space_id` text NOT NULL, `result_event_hash` text NOT NULL, `policy_version` text NOT NULL, `record` text NOT NULL, PRIMARY KEY (`space_id`, `result_event_hash`, `policy_version`), CONSTRAINT `continuations_result` FOREIGN KEY (`space_id`, `result_event_hash`) REFERENCES `events` (`space_id`, `hash`));
-- Create "notification_outbox" table
CREATE TABLE `notification_outbox` (`space_id` text NOT NULL, `notification_id` text NOT NULL, `record` text NOT NULL, `derived` integer NOT NULL DEFAULT 0, PRIMARY KEY (`space_id`, `notification_id`), CONSTRAINT `notification_outbox_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `notification_derived` CHECK (derived IN (0,1)));
-- Create "notification_acks" table
CREATE TABLE `notification_acks` (`space_id` text NOT NULL, `notification_id` text NOT NULL, `client_id` text NOT NULL, `event_hash` text NOT NULL DEFAULT '', PRIMARY KEY (`space_id`, `notification_id`, `client_id`), CONSTRAINT `notification_acks_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`));
-- Create "budget_days" table
CREATE TABLE `budget_days` (`space_id` text NOT NULL, `day` text NOT NULL, `used` integer NOT NULL, PRIMARY KEY (`space_id`, `day`), CONSTRAINT `budget_days_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `budget_nonnegative` CHECK (used >= 0));
-- Create "local_values" table
CREATE TABLE `local_values` (`space_id` text NOT NULL, `key` text NOT NULL, `value` text NOT NULL, PRIMARY KEY (`space_id`, `key`), CONSTRAINT `local_values_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`));
-- Create "identity_meta" table
CREATE TABLE `identity_meta` (`key` text NOT NULL, `value` text NOT NULL, PRIMARY KEY (`key`));
-- Create "event_dependencies" table
CREATE TABLE `event_dependencies` (`space_id` text NOT NULL, `child_hash` text NOT NULL, `parent_hash` text NOT NULL, PRIMARY KEY (`space_id`, `child_hash`, `parent_hash`), CONSTRAINT `dependencies_child` FOREIGN KEY (`space_id`, `child_hash`) REFERENCES `events` (`space_id`, `hash`));
-- Create "event_blobs" table
CREATE TABLE `event_blobs` (`space_id` text NOT NULL, `event_hash` text NOT NULL, `blob_hash` text NOT NULL, PRIMARY KEY (`space_id`, `event_hash`, `blob_hash`), CONSTRAINT `event_blobs_event` FOREIGN KEY (`space_id`, `event_hash`) REFERENCES `events` (`space_id`, `hash`));
-- Create "nonce_receipts" table
CREATE TABLE `nonce_receipts` (`space_id` text NOT NULL, `nonce` text NOT NULL, `body_hash` text NOT NULL, `request_body` text NOT NULL, `operation_id` text NOT NULL, `receipt` text NOT NULL, PRIMARY KEY (`space_id`, `nonce`), CONSTRAINT `nonces_operation_body` FOREIGN KEY (`space_id`, `operation_id`, `request_body`) REFERENCES `operations` (`space_id`, `operation_id`, `request`));
-- Create "policy_pins" table
CREATE TABLE `policy_pins` (`domain_kind` text NOT NULL, `domain_id` text NOT NULL, `genesis_root` text NOT NULL, `minimum_head` text NULL, PRIMARY KEY (`domain_kind`, `domain_id`), CONSTRAINT `policy_pins_kind` CHECK (domain_kind IN ('account', 'space')));
-- Create "policy_journal" table
CREATE TABLE `policy_journal` (`ordinal` integer NOT NULL, `entry_hash` text NOT NULL, `entry` text NOT NULL, `accepted_at_ms` integer NOT NULL, PRIMARY KEY (`ordinal`), CONSTRAINT `policy_journal_accepted_at` CHECK (accepted_at_ms >= 0));
-- Create index "policy_journal_entry_hash" to table: "policy_journal"
CREATE UNIQUE INDEX `policy_journal_entry_hash` ON `policy_journal` (`entry_hash`);
-- Create "current_policy_heads" table
CREATE TABLE `current_policy_heads` (`domain_kind` text NOT NULL, `domain_id` text NOT NULL, `authority_epoch` integer NOT NULL, `sequence` integer NOT NULL, `head_hash` text NOT NULL, PRIMARY KEY (`domain_kind`, `domain_id`), CONSTRAINT `current_policy_heads_kind` CHECK (domain_kind IN ('account', 'space')), CONSTRAINT `current_policy_heads_version` CHECK (authority_epoch >= 0 AND sequence >= 0));
-- Create "authorization_challenges" table
CREATE TABLE `authorization_challenges` (`space_id` text NOT NULL, `nonce` text NOT NULL, `invocation_hash` text NOT NULL, `stage` text NOT NULL, `challenge` text NOT NULL, `expires_at_ms` integer NOT NULL, `consumed` integer NOT NULL DEFAULT 0, PRIMARY KEY (`space_id`, `nonce`), CONSTRAINT `authorization_challenges_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `authorization_challenges_stage` CHECK (stage IN ('remote_read', 'admit', 'start', 'renew')), CONSTRAINT `authorization_challenges_expiry` CHECK (expires_at_ms >= 0), CONSTRAINT `authorization_challenges_consumed` CHECK (consumed IN (0,1)));
-- Create "accepted_authorizations" table
CREATE TABLE `accepted_authorizations` (`space_id` text NOT NULL, `authorization_id` text NOT NULL, `invocation_hash` text NOT NULL, `invocation_body_hash` text NOT NULL, `actor_kind` text NOT NULL, `actor_id` text NOT NULL, `device_id` text NOT NULL, `resource_id` text NOT NULL, `action` text NOT NULL, `grant_leaf` text NOT NULL, `signed_invocation` text NOT NULL, `source_body` text NOT NULL, `transport` text NOT NULL, `admission_challenge` text NOT NULL, `admission_receipts` text NOT NULL, `admitted_at_ms` integer NOT NULL, `operation_id` text NULL, PRIMARY KEY (`space_id`, `authorization_id`), CONSTRAINT `accepted_authorizations_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `accepted_authorizations_actor` CHECK (actor_kind IN ('account', 'service')), CONSTRAINT `accepted_authorizations_admitted_at` CHECK (admitted_at_ms >= 0));
-- Create index "accepted_authorizations_invocation" to table: "accepted_authorizations"
CREATE UNIQUE INDEX `accepted_authorizations_invocation` ON `accepted_authorizations` (`space_id`, `invocation_hash`);
-- Create "authorization_nonces" table
CREATE TABLE `authorization_nonces` (`space_id` text NOT NULL, `device_id` text NOT NULL, `nonce` text NOT NULL, `authorization_id` text NOT NULL, `body_hash` text NOT NULL, PRIMARY KEY (`space_id`, `device_id`, `nonce`), CONSTRAINT `authorization_nonces_authorization` FOREIGN KEY (`space_id`, `authorization_id`) REFERENCES `accepted_authorizations` (`space_id`, `authorization_id`));
-- Create "resource_records" table
CREATE TABLE `resource_records` (`space_id` text NOT NULL, `resource_id` text NOT NULL, `record_hash` text NOT NULL, `kind` text NOT NULL, `host_service_id` text NOT NULL, `signed_record` text NOT NULL, PRIMARY KEY (`space_id`, `resource_id`), CONSTRAINT `resource_records_space` FOREIGN KEY (`space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `resource_records_kind` CHECK (kind IN ('space_control', 'project', 'execution_service')));
-- Create index "resource_records_hash" to table: "resource_records"
CREATE UNIQUE INDEX `resource_records_hash` ON `resource_records` (`space_id`, `record_hash`);
-- Create "policy_nonces" table
CREATE TABLE `policy_nonces` (`domain_kind` text NOT NULL, `domain_id` text NOT NULL, `nonce` text NOT NULL, `entry_hash` text NOT NULL, PRIMARY KEY (`domain_kind`, `domain_id`, `nonce`), CONSTRAINT `policy_nonces_entry` FOREIGN KEY (`entry_hash`) REFERENCES `policy_journal` (`entry_hash`), CONSTRAINT `policy_nonces_kind` CHECK (domain_kind IN ('account', 'space')));
-- Create "passkey_pending" table
CREATE TABLE `passkey_pending` (`account_id` text NOT NULL, `envelope_hash` text NOT NULL, `intent_hash` text NOT NULL, `nonce` text NOT NULL, `pending` text NOT NULL, `expires_at_ms` integer NOT NULL, PRIMARY KEY (`account_id`, `envelope_hash`), CONSTRAINT `passkey_pending_expiry` CHECK (expires_at_ms >= 0));
-- Create index "passkey_pending_account_nonce" to table: "passkey_pending"
CREATE UNIQUE INDEX `passkey_pending_account_nonce` ON `passkey_pending` (`account_id`, `nonce`);
-- Create index "passkey_pending_account_intent" to table: "passkey_pending"
CREATE UNIQUE INDEX `passkey_pending_account_intent` ON `passkey_pending` (`account_id`, `intent_hash`);
-- Create "passkey_authenticators" table
CREATE TABLE `passkey_authenticators` (`account_id` text NOT NULL, `credential_id` text NOT NULL, `rp_id` text NOT NULL, `record_hash` text NOT NULL, `sign_count` integer NOT NULL, `backup_state` integer NOT NULL, `last_envelope_hash` text NOT NULL, PRIMARY KEY (`account_id`, `credential_id`), CONSTRAINT `passkey_authenticators_pending` FOREIGN KEY (`account_id`, `last_envelope_hash`) REFERENCES `passkey_pending` (`account_id`, `envelope_hash`), CONSTRAINT `passkey_authenticators_counter` CHECK (sign_count BETWEEN 0 AND 4294967295), CONSTRAINT `passkey_authenticators_backup` CHECK (backup_state IN (0, 1)));
-- Create index "passkey_authenticators_rp_credential" to table: "passkey_authenticators"
CREATE UNIQUE INDEX `passkey_authenticators_rp_credential` ON `passkey_authenticators` (`rp_id`, `credential_id`);
-- Create index "passkey_authenticators_record" to table: "passkey_authenticators"
CREATE UNIQUE INDEX `passkey_authenticators_record` ON `passkey_authenticators` (`record_hash`);
-- Create "passkey_receipts" table
CREATE TABLE `passkey_receipts` (`account_id` text NOT NULL, `envelope_hash` text NOT NULL, `completion_hash` text NOT NULL, `receipt` text NOT NULL, `accepted_at_ms` integer NOT NULL, PRIMARY KEY (`account_id`, `envelope_hash`), CONSTRAINT `passkey_receipts_pending` FOREIGN KEY (`account_id`, `envelope_hash`) REFERENCES `passkey_pending` (`account_id`, `envelope_hash`), CONSTRAINT `passkey_receipts_accepted_at` CHECK (accepted_at_ms >= 0));
-- Create "execution_binding_seals" table
CREATE TABLE `execution_binding_seals` (`original_space_id` text NOT NULL, `original_resource_id` text NOT NULL, `task_ref` text NOT NULL, `target_node` text NOT NULL, `generation` integer NOT NULL, `execution_space_id` text NOT NULL, `execution_resource_id` text NOT NULL, `binding_hash` text NOT NULL, `seal_invocation_hash` text NOT NULL, `admission` text NOT NULL, `seal` text NOT NULL, PRIMARY KEY (`original_space_id`, `original_resource_id`, `task_ref`, `target_node`, `generation`), CONSTRAINT `binding_seals_node` FOREIGN KEY (`execution_space_id`, `target_node`) REFERENCES `node_certificates` (`space_id`, `node_id`), CONSTRAINT `binding_seals_space` FOREIGN KEY (`execution_space_id`) REFERENCES `spaces` (`space_id`), CONSTRAINT `binding_seals_generation` CHECK (generation >= 1), CONSTRAINT `binding_seals_admission_json` CHECK (json_valid(admission)), CONSTRAINT `binding_seals_seal_json` CHECK (json_valid(seal)));
-- Create index "binding_seals_invocation_once" to table: "execution_binding_seals"
CREATE UNIQUE INDEX `binding_seals_invocation_once` ON `execution_binding_seals` (`execution_space_id`, `seal_invocation_hash`);
-- Create "execution_handoffs" table
CREATE TABLE `execution_handoffs` (`execution_space_id` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `target_node` text NOT NULL, `session_id` text NULL, `original_request` text NOT NULL, `handoff` text NOT NULL, `handoff_hash` text NOT NULL, `invocation_hash` text NOT NULL, `body_hash` text NOT NULL, `admission_transport` text NOT NULL, `admission_challenge` text NOT NULL, `admission_receipts` text NOT NULL, `admission_receipt` text NOT NULL, `admitted_at_ms` integer NOT NULL, `state` text NOT NULL, `control` integer NOT NULL, `result` text NOT NULL, `lease_challenge` text NULL, `lease_receipts` text NULL, `lease_verified_at_ms` integer NULL, `lease_deadline_ms` integer NULL, `result_receipt` text NULL, PRIMARY KEY (`execution_space_id`, `original_space_id`, `operation_id`), CONSTRAINT `execution_handoffs_fk_0` FOREIGN KEY (`execution_space_id`, `target_node`) REFERENCES `node_certificates` (`space_id`, `node_id`), CONSTRAINT `execution_handoffs_fk_2` FOREIGN KEY (`execution_space_id`) REFERENCES `spaces` (`space_id`), CHECK (json_valid(admission_receipt)), CONSTRAINT `handoff_request_json` CHECK (json_valid(original_request) AND json_valid(handoff)), CONSTRAINT `handoff_request_session` CHECK (COALESCE(CASE json_extract(original_request, '$.action.type') WHEN 'command' THEN session_id IS NULL AND json_type(original_request, '$.session_id') = 'null' AND json_type(original_request, '$.task_id') = 'null' AND COALESCE(json_type(original_request, '$.binding'), 'null') = 'null' AND json_extract(original_request, '$.expected_revision') = 0 ELSE json_extract(original_request, '$.action.type') IN ('open','read','send','steer','interrupt','respond_request') AND session_id IS NOT NULL AND length(session_id) > 0 AND json_extract(original_request, '$.session_id') = session_id END, 0)), CONSTRAINT `handoff_work_session` CHECK (COALESCE((json_extract(handoff, '$.handoff.source_attestation.payload.work.kind') = 'command' AND session_id IS NULL) OR (json_extract(handoff, '$.handoff.source_attestation.payload.work.kind') IN ('task_session','conversation_session') AND session_id IS NOT NULL AND json_extract(handoff, '$.handoff.source_attestation.payload.work.execution_session.session_id') = session_id), 0)), CHECK (admitted_at_ms >= 0), CHECK (state IN ('accepted','running','unknown','succeeded','failed','rejected')), CHECK (control IN (0,1)), CHECK ((lease_challenge IS NULL AND lease_receipts IS NULL AND lease_verified_at_ms IS NULL AND lease_deadline_ms IS NULL)
     OR (lease_challenge IS NOT NULL AND lease_receipts IS NOT NULL
         AND lease_verified_at_ms IS NOT NULL AND lease_deadline_ms IS NOT NULL
         AND lease_verified_at_ms >= 0 AND lease_deadline_ms > lease_verified_at_ms)));
-- Create index "handoffs_dispatch_once" to table: "execution_handoffs"
CREATE UNIQUE INDEX `handoffs_dispatch_once` ON `execution_handoffs` (`execution_space_id`, `handoff_hash`);
-- Create index "handoffs_invocation_once" to table: "execution_handoffs"
CREATE UNIQUE INDEX `handoffs_invocation_once` ON `execution_handoffs` (`execution_space_id`, `invocation_hash`);
-- Create index "handoffs_original_operation_once" to table: "execution_handoffs"
CREATE UNIQUE INDEX `handoffs_original_operation_once` ON `execution_handoffs` (`original_space_id`, `operation_id`);
-- Create "execution_handoff_challenges" table
CREATE TABLE `execution_handoff_challenges` (`execution_space_id` text NOT NULL, `nonce` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `handoff_hash` text NOT NULL, `stage` text NOT NULL, `challenge` text NOT NULL, `expires_at_ms` integer NOT NULL, `consumed` integer NOT NULL DEFAULT 0, PRIMARY KEY (`execution_space_id`, `nonce`), CONSTRAINT `execution_handoff_challenges_fk_1` FOREIGN KEY (`execution_space_id`) REFERENCES `spaces` (`space_id`), CHECK (stage IN ('admit','start','renew','remote_read')), CHECK (expires_at_ms >= 0), CHECK (consumed IN (0,1)));
-- Create "execution_handoff_nonces" table
CREATE TABLE `execution_handoff_nonces` (`execution_space_id` text NOT NULL, `device_id` text NOT NULL, `nonce` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `invocation_hash` text NOT NULL, `body_hash` text NOT NULL, PRIMARY KEY (`execution_space_id`, `device_id`, `nonce`), CONSTRAINT `execution_handoff_nonces_fk_0` FOREIGN KEY (`execution_space_id`, `original_space_id`, `operation_id`) REFERENCES `execution_handoffs` (`execution_space_id`, `original_space_id`, `operation_id`));
-- Create index "handoff_nonce_operation_once" to table: "execution_handoff_nonces"
CREATE UNIQUE INDEX `handoff_nonce_operation_once` ON `execution_handoff_nonces` (`execution_space_id`, `original_space_id`, `operation_id`);
-- Create "execution_handoff_reservations" table
CREATE TABLE `execution_handoff_reservations` (`execution_space_id` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `target_node` text NOT NULL, `resource` text NOT NULL, PRIMARY KEY (`execution_space_id`, `original_space_id`, `operation_id`, `resource`), CONSTRAINT `execution_handoff_reservations_fk_0` FOREIGN KEY (`execution_space_id`, `original_space_id`, `operation_id`) REFERENCES `execution_handoffs` (`execution_space_id`, `original_space_id`, `operation_id`));
-- Create "execution_handoff_sessions" table
CREATE TABLE `execution_handoff_sessions` (`execution_space_id` text NOT NULL, `original_space_id` text NOT NULL, `original_resource_id` text NOT NULL, `target_node` text NOT NULL, `session_id` text NOT NULL, `revision` integer NOT NULL, `binding` text NULL, `record` text NOT NULL, PRIMARY KEY (`execution_space_id`, `original_space_id`, `original_resource_id`, `target_node`, `session_id`), CONSTRAINT `execution_handoff_sessions_fk_0` FOREIGN KEY (`execution_space_id`, `target_node`) REFERENCES `node_certificates` (`space_id`, `node_id`), CHECK (revision >= 0), CONSTRAINT `handoff_session_record_json` CHECK (json_valid(record)), CONSTRAINT `handoff_session_work` CHECK (COALESCE(json_extract(record, '$.session_id') = session_id AND json_extract(record, '$.work.execution_session.session_id') = session_id AND json_extract(record, '$.revision') = revision AND ((json_extract(record, '$.work.kind') = 'task_session' AND binding IS NOT NULL AND json_valid(binding) AND json_type(binding) = 'object') OR (json_extract(record, '$.work.kind') = 'conversation_session' AND binding IS NULL)), 0)));
-- Create "execution_handoff_resolution_challenges" table
CREATE TABLE `execution_handoff_resolution_challenges` (`execution_space_id` text NOT NULL, `nonce` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `resolution_id` text NOT NULL, `resolution_hash` text NOT NULL, `challenge` text NOT NULL, `expires_at_ms` integer NOT NULL, `consumed` integer NOT NULL DEFAULT 0, PRIMARY KEY (`execution_space_id`, `nonce`), CONSTRAINT `execution_handoff_resolution_challenges_fk_0` FOREIGN KEY (`execution_space_id`, `original_space_id`, `operation_id`) REFERENCES `execution_handoffs` (`execution_space_id`, `original_space_id`, `operation_id`), CHECK (expires_at_ms >= 0), CHECK (consumed IN (0,1)));
-- Create "execution_handoff_resolutions" table
CREATE TABLE `execution_handoff_resolutions` (`execution_space_id` text NOT NULL, `original_space_id` text NOT NULL, `operation_id` text NOT NULL, `resolution_id` text NOT NULL, `resolution_hash` text NOT NULL, `resolver_device` text NOT NULL, `resolver_nonce` text NOT NULL, `resolver_invocation_hash` text NOT NULL, `resolver_body_hash` text NOT NULL, `submission_device` text NOT NULL, `submission_nonce` text NOT NULL, `submission_invocation_hash` text NOT NULL, `submission_body_hash` text NOT NULL, `request` text NOT NULL, `admission_transport` text NOT NULL, `freshness` text NOT NULL, `resolved_at_ms` integer NOT NULL, `result_receipt` text NOT NULL, PRIMARY KEY (`execution_space_id`, `original_space_id`, `operation_id`), CONSTRAINT `execution_handoff_resolutions_fk_0` FOREIGN KEY (`execution_space_id`, `original_space_id`, `operation_id`) REFERENCES `execution_handoffs` (`execution_space_id`, `original_space_id`, `operation_id`), CHECK (resolved_at_ms >= 0));
-- Create index "handoff_resolution_id_once" to table: "execution_handoff_resolutions"
CREATE UNIQUE INDEX `handoff_resolution_id_once` ON `execution_handoff_resolutions` (`original_space_id`, `resolution_id`);
-- Create index "handoff_resolution_resolver_nonce_once" to table: "execution_handoff_resolutions"
